(() => {
 const bot='https://t.me/coferappbot',community='https://t.me/usecoferonRH',xPage='https://x.com/UseCofer';
 const newTab=new Set([community,xPage]);
 const destinations={'Open in Telegram':bot,'Telegram bot':bot,'Telegram':community,'Community':community,'X / Twitter':xPage,'Features':'#platform','Explore account':'#platform','Shared account':'#platform','Shares':'#platform','Group buys':'#platform','How it works':'/how-it-works.html','Friends':'#flow','Travel':'#flow','Communities':'#flow','The system':'#system','Experience':'#developers','Explore how it works':'/how-it-works.html','Account rules':'#proof','Development':'#proof','Rules':'#proof','Questions':'#proof','Explore':'#platform'};
 const icons={GitHub:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 .8a11.2 11.2 0 0 0-3.54 21.83c.56.1.77-.24.77-.54v-2.16c-3.14.68-3.8-1.33-3.8-1.33-.51-1.3-1.25-1.65-1.25-1.65-1.02-.7.08-.69.08-.69 1.13.08 1.73 1.16 1.73 1.16 1 1.72 2.63 1.22 3.27.93.1-.72.39-1.22.7-1.5-2.51-.29-5.15-1.26-5.15-5.58 0-1.23.44-2.23 1.16-3.02-.12-.28-.5-1.43.11-2.98 0 0 .94-.3 3.08 1.15a10.7 10.7 0 0 1 5.6 0c2.14-1.45 3.08-1.15 3.08-1.15.61 1.55.23 2.7.11 2.98.72.79 1.15 1.79 1.15 3.02 0 4.33-2.64 5.29-5.16 5.57.4.35.76 1.03.76 2.08v3.07c0 .3.2.65.77.54A11.2 11.2 0 0 0 12 .8z"/></svg>','X / Twitter':'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M18.9 2H22l-6.8 7.8L23.2 22H17l-4.9-7.4L5.6 22H2.5l7.2-8.3L1.9 2h6.4l4.4 6.7L18.9 2zm-1.1 18h1.7L7.4 3.9H5.6L17.8 20z"/></svg>',Telegram:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M21.5 3.2 2.6 10.5c-1.3.5-1.3 1.2-.2 1.5l4.9 1.5 1.9 5.8c.2.6.1.9.8.9.5 0 .8-.2 1.1-.5l2.4-2.3 5 3.7c.9.5 1.6.3 1.8-.8L23 4.5c.3-1.3-.5-1.8-1.5-1.3zM8 13.2 19 6.3c.5-.3.9-.1.5.2l-9.1 8.2-.4 4-2-5.5z"/></svg>'};
 icons.Community=icons.Telegram;
 let previousFocus;
 function dialog(){let d=document.getElementById('cofer-social-dialog');if(d)return d;d=document.createElement('dialog');d.id='cofer-social-dialog';d.innerHTML='<button type="button" aria-label="Close">×</button><p class="cofer-dialog-label">COFER / SOCIAL</p><h2>Coming soon.</h2><p>We’re getting this space ready. Check back for updates.</p>';document.body.append(d);d.querySelector('button').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d)d.close()});d.addEventListener('close',()=>previousFocus?.focus());return d}
 function textOf(a){return a.textContent.replace(/^\s*\d{2}\s*/,'').replace(/[↗→]/g,'').trim()}
 function update(a){if(a.closest('.cofer-landing-header'))return;const label=textOf(a),target=destinations[label];if(target&&a.getAttribute('href')!==target)a.setAttribute('href',target);if(newTab.has(target)){a.setAttribute('target','_blank');a.setAttribute('rel','noopener noreferrer');if(label==='Telegram'){for(const n of a.childNodes)if(n.nodeType===Node.TEXT_NODE&&n.data.trim()==='Telegram')n.data=n.data.replace('Telegram','Community');a.setAttribute('aria-label','Cofer community on Telegram (opens in a new tab)')}}if(icons[label]&&!a.querySelector('svg'))a.insertAdjacentHTML('afterbegin',icons[label]);if(icons[label]&&!target){a.dataset.coferSocial=label;a.setAttribute('href','#social');a.setAttribute('role','button');a.removeAttribute('target');a.setAttribute('aria-label',label+' — coming soon')}}
 function updateWithin(node){if(node.nodeType===Node.TEXT_NODE){const a=node.parentElement?.closest('a');if(a)update(a);return}if(!(node instanceof Element)||/^(STYLE|SCRIPT|LINK|META|SVG|PATH)$/.test(node.tagName)||node.closest('.cofer-landing-header'))return;const heading=node.matches('h1')?node:node.querySelector('h1');if(heading)heading.setAttribute('aria-label','Your group chat gets a shared account. Everyone has a say.');if(node.matches('a'))update(node);node.querySelectorAll('a').forEach(update);const a=node.parentElement?.closest('a');if(a)update(a)}
 function openSocial(a){previousFocus=a;const d=dialog();if(!d.open)d.showModal()}
 document.addEventListener('keydown',e=>{const social=e.target.closest?.('a[data-cofer-social]');if(social&&e.key===' '){e.preventDefault();openSocial(social)}},true);
 document.addEventListener('click',e=>{const a=e.target.closest?.('a');if(!a||a.closest('.cofer-landing-header'))return;const label=textOf(a),target=destinations[label];if(!target&&(a.dataset.coferSocial||icons[label]||/github\.com|(?:^|\/)x\.com|linkedin\.com|t\.me/.test(a.getAttribute('href')||''))){e.preventDefault();e.stopImmediatePropagation();openSocial(a);return}if(target&&newTab.has(target)){a.setAttribute('href',target);a.setAttribute('target','_blank');a.setAttribute('rel','noopener noreferrer');return}if(!target||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;e.preventDefault();e.stopImmediatePropagation();if(target.startsWith('#')){history.pushState(null,'',target);const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;document.querySelector(target)?.scrollIntoView({behavior:reduced?'auto':'smooth'})}else location.assign(target)},true);
 const fixTitle=()=>{if(document.title!=='Cofer — Your group chat gets a shared account')document.title='Cofer — Your group chat gets a shared account'};fixTitle();const titleNode=document.querySelector('title');if(titleNode)new MutationObserver(fixTitle).observe(titleNode,{childList:true,characterData:true,subtree:true});document.querySelectorAll('a').forEach(update);const heading=document.querySelector('h1');if(heading)heading.setAttribute('aria-label','Your group chat gets a shared account. Everyone has a say.');
 const observer=new MutationObserver(records=>{for(const record of records){for(const node of record.addedNodes)updateWithin(node)}});observer.observe(document.documentElement,{childList:true,subtree:true});
})();
